echo "C300: c_deploy_p2"
N=/workspace/nox; W=$N/web/pkg/server; L=$N/svc/living; P=$N/svc/pipeline; mkdir -p $P
echo "=== files"
echo  | base64 -d > $P/pipeline_svc.py
echo  | base64 -d > $P/patch_pipe.py
echo  | base64 -d > $P/c_test.py
cat > $P/c_bg1.sh <<'BGEOF'
#!/bin/bash
W=/workspace/nox/web/pkg/server; O=/workspace/nox/state/c_test1.out; : > $O
{ echo "== direct verdict"; curl -s -m30 localhost:18217/verdict -H 'Content-Type: application/json' -d '{"q":"Сколько будет 12*12? Ответь коротко.","answer":"144","cid":"ctest0"}'; echo
echo "== turn1 (first delta/done/meta2)"; timeout 230 python3 /workspace/nox/svc/pipeline/c_test.py "Сколько будет 12*12? Ответь коротко." ctest1 220
echo "== turn2 quote/reply"; timeout 200 python3 /workspace/nox/svc/pipeline/c_test.py "Почему так?" ctest2 190 '{"quote":"12*12=144","reply_to":{"index":1,"role":"assistant","preview":"144"}}'
echo "== meta after"; curl -s localhost:18215/meta?cid=ctest1; echo
echo "== saved conv"; ls $W/../../data/conversations 2>/dev/null | head -2
} >> $O 2>&1
if grep -q '"t"\|^done\|ANSWER' $O && grep -q "^done" $O; then echo CHAT_OK >> $O; else echo "CHAT_FAIL -> rollback" >> $O; cp $W/chat_core.py.bak_c_1 $W/chat_core.py; ( $W/run_web.sh restart </dev/null >/tmp/c_web_restart.log 2>&1 ); fi
echo FINISHED >> $O
BGEOF
chmod +x $P/c_bg1.sh; python3 -m py_compile $P/pipeline_svc.py && echo pipeline_compile_ok
echo "=== ddgs (готовая библиотека поиска)"; ( timeout 80 $N/venv_living/bin/pip install -q ddgs >$P/pip.log 2>&1 </dev/null & ); true
echo "=== living /metaset"
[ -f $L/living_svc.py.bak_c_1 ] || cp $L/living_svc.py $L/living_svc.py.bak_c_1
python3 - <<'PYEOF'
p="/workspace/nox/svc/living/living_svc.py"; s=open(p,encoding="utf-8").read()
if "/metaset" in s: print("living already patched")
else:
    k='            if p == "/incognito":'
    assert s.count(k)==1, s.count(k)
    s=s.replace(k,'            if p == "/metaset":\n                _c = str(b.get("cid") or "x"); LASTMETA[_c] = dict(LASTMETA.get(_c) or {}, **(b.get("meta") or {})); return self._j({"ok": True})\n'+k,1)
    open(p,"w",encoding="utf-8").write(s); print("living patched")
PYEOF
python3 -m py_compile $L/living_svc.py && echo living_compile_ok || { cp $L/living_svc.py.bak_c_1 $L/living_svc.py; echo living_rollback; }
pkill -f living_svc.py; sleep 1; ( cd $L && nohup setsid $N/venv_living/bin/python living_svc.py >logs/living.log 2>&1 </dev/null & ); sleep 2
echo "=== start pipeline"
pkill -f pipeline_svc.py; sleep 1; ( cd $P && nohup setsid $N/venv_living/bin/python pipeline_svc.py >$P/pipeline.log 2>&1 </dev/null & ); sleep 2
S=$N/svc/start_extra.sh; [ -f $S.bak_c_1 ] || cp $S $S.bak_c_1
grep -q 18217 $S || echo '(echo > /dev/tcp/127.0.0.1/18217) 2>/dev/null || { cd /workspace/nox/svc/pipeline && nohup setsid /workspace/nox/venv_living/bin/python pipeline_svc.py >pipeline.log 2>&1 </dev/null & }' >> $S
curl -s -m4 localhost:18217/health; echo; curl -s -m4 localhost:18215/status | head -c 120; echo
echo "=== persona flag"
cp $N/state/persona.json $N/state/persona.json.bak_c_1
python3 -c "import json;p='/workspace/nox/state/persona.json';d=json.load(open(p));d['living_engines']=dict(d.get('living_engines') or {},pipeline=True);json.dump(d,open(p,'w'),ensure_ascii=False,indent=1);print(d['living_engines'])"
echo "=== chat_core patch"
[ -f $W/chat_core.py.bak_c_1 ] || cp $W/chat_core.py $W/chat_core.py.bak_c_1
python3 $P/patch_pipe.py && python3 -m py_compile $W/chat_core.py && echo cc_compile_ok || { cp $W/chat_core.py.bak_c_1 $W/chat_core.py; echo cc_rollback; }
( $W/run_web.sh restart </dev/null >/tmp/c_web_restart.log 2>&1 ); sleep 8; tail -2 /tmp/c_web_restart.log
echo "=== background test (read result with c_fetch*)"
nohup setsid bash $P/c_bg1.sh >/dev/null 2>&1 </dev/null &
sleep 1; echo started
